    <label>Current or target Mach</label>
    <div class="stepper"><button type="button" data-t="mach" data-d="-0.01">−</button><input id="mach" type="number" step="0.01" inputmode="decimal"><button type="button" data-t="mach" data-d="0.01">+</button></div>
    <div class="err" id="err-mach"></div><div class="warn" id="warn-mach"></div>
  </div></div>

  <div class="card"><h2 data-acc>Aircraft limits <span class="arw">–</span></h2><div class="body">
