th:first-child,td:first-child{text-align:left;white-space:normal}
.track{position:relative;height:42px;background:var(--p3);border:1px solid var(--ln);border-radius:5px;margin:18px 0 4px}
.zone{position:absolute;top:0;bottom:0}
.zraw{background:rgba(255,176,32,.15);border-left:1px dashed rgba(255,176,32,.55);border-right:1px dashed rgba(255,176,32,.55)}
.zsafe{background:rgba(61,220,132,.25);border-left:2px solid var(--gr);border-right:2px solid var(--gr)}
.mk{position:absolute;top:0;bottom:0;width:3px;transform:translateX(-1.5px)}
.mk.st{background:var(--rd)}.mk.cl{background:var(--rd)}
.mk.cu{width:0;height:0;border-left:7px solid transparent;border-right:7px solid transparent;border-top:12px solid #fff;top:auto;bottom:-2px;transform:translateX(-7px)}
.lab{position:absolute;top:2px;font-size:10px;font-weight:700;white-space:nowrap;text-shadow:0 0 4px var(--p3)}
.lab.st,.lab.cl{color:var(--rd)}.lab.cur{color:var(--tx);bottom:15px;top:auto}
.scale{position:relative;height:14px;font-size:10px;color:var(--gy)}
.scale span{position:absolute;transform:translateX(-50%)}
.nb{border-left:4px solid var(--am);background:rgba(255,176,32,.09);padding:8px 10px;border-radius:4px;font-size:12.5px;margin-bottom:7px}
.nb.bad{border-left-color:var(--rd);background:rgba(255,82,82,.1)}
.nb.info{border-left-color:var(--bl);background:rgba(99,184,255,.09)}
.nb.ok{border-left-color:var(--gr);background:rgba(61,220,132,.09)}
pre.eq{background:var(--p3);border:1px solid var(--ln);padding:9px;border-radius:6px;font-size:11.5px;overflow-x:auto;white-space:pre;margin:6px 0;line-height:1.55;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
pre.eq b{color:var(--am)}
.notes{font-size:12.5px;color:var(--dm);margin:0;padding-left:18px}
.notes li{margin-bottom:5px}
.tag{display:inline-block;font-size:9.5px;padding:1px 5px;border-radius:3px;border:1px solid var(--ln);color:var(--gy);vertical-align:middle;margin-left:4px}
.tag.ill{color:var(--am);border-color:var(--am)}.tag.pub{color:var(--bl);border-color:var(--bl)}
