</div>

<div class="g" style="margin-top:6px">
<div><label>VMO (KIAS)</label><input id="vmo" type="number" step="1" value="340"></div>
<div><label>MMO general (Mach)</label><input id="mmo" type="number" step="0.01" value="0.81"></div>
<div><label>Stepped limit above (ft)</label><input id="stepAlt" type="number" step="1000" value="37000"></div>
