<script>
"use strict";
var R=287.05287,GAM=1.4,RHO0=1.225,KT=1.687809857,MPH=1.150779448,PSF=47.8803;
var T0=288.15,P0=101325,LC=0.0065,GG=9.80665,KEY='ccL_';
var BOOT=false,CUSTOM=false,STEPMODE='ge',NCHECK=20;

function $(id){return document.getElementById(id);}
function T(id,t){var e=$(id);if(e){e.textContent=t;}return e;}
function H(id,h){var e=$(id);if(e){e.innerHTML=h;}return e;}
function num(id){var e=$(id);if(!e)return null;var v=parseFloat(e.value);return isNaN(v)?null:v;}
function F(v,d){if(v===null||v===undefined||!isFinite(v))return '--';return Number(v).toFixed(d===undefined?2:d);}
function K(v){return F(v,1);}
function N(v){if(v===null||v===undefined||!isFinite(v))return '--';return Number(v).toLocaleString('en-US',{maximumFractionDigits:0});}

function isaAt(hf){
  var hm=Math.max(0,Math.min(65000,hf||0))*0.3048,TT,p;
  if(hm<=11000){TT=T0-LC*hm;p=P0*Math.pow(1-LC*hm/T0,5.25588);}
  else{TT=216.65;p=22632.1*Math.exp(-GG*(hm-11000)/(R*TT));}
  return {T:TT,p:p,Tc:TT-273.15};
}
function atmos(hf,oatC){
  var I=isaAt(hf),have=(oatC!==null&&!isNaN(oatC));
  var TT=have?(oatC+273.15):I.T;
  var rho=I.p/(R*TT),sig=rho/RHO0;
  var aMs=Math.sqrt(GAM*R*TT),aKt=aMs*KT,ss=Math.sqrt(sig);
  var dev=have?(I.Tc-oatC):0;
  return {T_isa:I.T,Tc_isa:I.Tc,p:I.p,rho:rho,sig:sig,ss:ss,aMs:aMs,aKt:aKt,aMph:aMs*MPH,
          dev:dev,aSig:aKt*ss,geom:have?hf*(1-dev/T0):null};
}
var REF=(function(){
  var I=isaAt(35000),rho=I.p/(R*I.T),aMs=Math.sqrt(GAM*R*I.T),V=0.76*aMs;
  return {rho:rho,aMs:aMs,V:V,q:0.5*rho*V*V};
})();

var RULES={
 weight:{min:500,max:250000,label:'Weight',unit:'lb',def:27500},
 wRef:{min:500,max:250000,label:'Reference weight',unit:'lb',def:27500},
 vsRef:{min:30,max:450,label:'Stall speed at ref weight',unit:'KIAS',def:185},
 cfgInc:{min:0,max:150,label:'Config increment',unit:'KIAS',def:0},
 vmo:{min:80,max:700,label:'VMO',unit:'KIAS',def:340},
 mmo:{min:0.20,max:1.00,label:'MMO',unit:'Mach',def:0.81},
 stepAlt:{min:0,max:65000,label:'Stepped altitude',unit:'ft',def:37000},
 stepMach:{min:0.20,max:1.00,label:'Stepped MMO',unit:'Mach',def:0.78},
 alt:{min:-500,max:65000,label:'Pressure altitude',unit:'ft',def:35000},
 oat:{min:-110,max:60,label:'OAT',unit:'deg C',def:null},
 ice:{min:0,max:60,label:'Ice penalty',unit:'%',def:0},
 mach:{min:0.05,max:1.30,label:'Mach',unit:'',def:0.76},
 mStall:{min:0,max:60,label:'Stall margin',unit:'kt',def:10},
 mVmo:{min:0,max:60,label:'Ceiling margin',unit:'kt',def:10}
};

function resolve(){
  var val={},issues=[];
  for(var k in RULES){
    var r=RULES[k],v=num(k);
    if(v===null||!isFinite(v)){
      if(k==='oat'){val[k]=null;continue;}
      val[k]=r.def;
      issues.push(r.label+' is blank - using default '+r.def+' '+r.unit);
    }else if(v<r.min){
      val[k]=r.min;issues.push(r.label+' below minimum - clamped to '+r.min);
    }else if(v>r.max){
      val[k]=r.max;issues.push(r.label+' above maximum - clamped to '+r.max);
    }else{val[k]=v;}
  }
  if((val.stepAlt===null)!==(val.stepMach===null)){
    issues.push('Enter BOTH the stepped altitude and the stepped MMO, or neither.');
    val.stepAlt=null;val.stepMach=null;
  }
  if(val.alt>50000)issues.push('Above FL500 - beyond any business-jet service ceiling');
  if(val.ice>25)issues.push('Ice penalty above the severe-icing range - verify');
  if(val.weight>val.wRef*1.02)issues.push('Above reference weight - the sqrt(W) scaling is first-order');
  return {val:val,issues:issues};
}

function compute(v){
  var A=atmos(v.alt,v.oat);
  var vsW=v.vsRef*Math.sqrt(v.weight/v.wRef)+v.cfgInc;
  var vsIce=vsW*(1+v.ice/100);
  var aSig=A.aSig;
  var unitOK=(aSig>100&&aSig<700);
  var Mstall=vsIce/aSig,MstallClean=vsW/aSig;
  var iasNow=v.mach*aSig,tasNow=v.mach*A.aKt;
  var stepOn=false;
  if(v.stepAlt!==null&&v.stepMach!==null){
    stepOn=(STEPMODE==='gt')?(v.alt>v.stepAlt):(v.alt>=v.stepAlt);
  }
  var mmoEff=stepOn?v.stepMach:v.mmo;
  var mFromVmo=v.vmo/aSig;
  var ceilM=mmoEff,mmoLbl='MMO';
  if(mFromVmo<ceilM){ceilM=mFromVmo;mmoLbl='VMO '+v.vmo+' KIAS';}
  else if(stepOn){mmoLbl='MMO (stepped)';}
  var iasCeil=ceilM*aSig,tasCeil=ceilM*A.aKt;
  var floorM=(vsIce+v.mStall)/aSig,ceilPol=ceilM-(v.mVmo)/aSig;
  var closed=(floorM>=ceilPol);
  var rawBandKt=iasCeil-vsIce,winKt=(ceilPol-floorM)*aSig;
  var VV=v.mach*A.aMs,qNow=0.5*A.rho*VV*VV;
  var densFac=A.rho/REF.rho,spdFac=Math.pow(VV/REF.V,2),qRatio=qNow/REF.q;
  var qCeil=0.5*A.rho*Math.pow(ceilM*A.aMs,2);
  var stallKt=iasNow-vsIce,ceilKt=iasCeil-iasNow;
  var overM=v.mach>ceilM+1e-9,underS=v.mach<Mstall-1e-9;
  var underFloor=v.mach<floorM+1e-9,overPol=v.mach>ceilPol+1e-9;
  var verdict='GO',vcls='go',reasons=[],actions=[],adv=[];
  if(!unitOK){
    verdict='UNIT ERROR SUSPECTED';vcls='no';
    reasons.push('a*sqrt(sigma) = '+F(aSig,1)+' kt is outside the plausible range 100-700 kt. Results are not trustworthy.');
    actions.push('Do not use these figures.');
  }else if(closed){
    verdict='NO-GO - BAND CLOSED';vcls='no';
    reasons.push('No speed exists that is simultaneously '+F(v.mStall,0)+' kt above the icing stall (M'+F(floorM,3)+') and '+F(v.mVmo,0)+' kt below the ceiling (M'+F(ceilPol,3)+').');
    actions.push('DESCEND. Change altitude, not speed - the ceiling cannot be raised, but the floor can be lowered by getting out of the ice.');
  }else if(overM){
    verdict='NO-GO - OVERSPEED';vcls='no';
    reasons.push('Mach '+F(v.mach,3)+' exceeds the '+mmoLbl+' ceiling of M'+F(ceilM,3)+'.');
    actions.push('Reduce speed and level the wings. Above the AFM limit there is NO demonstrated structural or flutter margin - the tail is the likely first failure.');
  }else if(underS){
    verdict='NO-GO - BELOW STALL';vcls='no';
    reasons.push('Mach '+F(v.mach,3)+' is below the icing-adjusted stall Mach M'+F(Mstall,3)+' ('+F(vsIce,1)+' KIAS).');
    actions.push('Add energy now: pitch up, increase thrust. Expect little or no buffet warning in ice and a possible asymmetric break.');
  }else if(underFloor){
    verdict='NO-GO - STALL MARGIN INSUFFICIENT';vcls='no';
    reasons.push('Only '+F(stallKt,1)+' kt above the icing stall; policy requires '+F(v.mStall,0)+' kt.');
    actions.push('Increase to at least M'+F(floorM,3)+' if the ceiling allows, or descend out of the icing.');
  }else if(overPol){
    verdict='CAUTION - OVERSPEED MARGIN INSUFFICIENT';vcls='caution';
    reasons.push('Below the hard ceiling but only '+F(ceilKt,1)+' kt below it; policy requires '+F(v.mVmo,0)+' kt.');
    actions.push('Reduce Mach toward M'+F(ceilPol,3)+', or descend to open the band.');
  }else{
    verdict='GO';vcls='go';
    reasons.push('Mach '+F(v.mach,3)+' sits inside the policy window with '+F(stallKt,1)+' kt above the icing stall and '+F(ceilKt,1)+' kt below the ceiling.');
  }
  if(stepOn)adv.push({c:'info',t:'<b>Stepped limit applies at this altitude</b> ('+mmoLbl+'). The more restrictive limit binds.'});
  if(overM||overPol)adv.push({c:'bad',t:'At or near the AFM speed limit. Beyond MMO there is no demonstrated margin - control-surface flutter and structural overstress become credible, and the elevator/empennage are the likely first failures.'});
  if(v.ice>0)adv.push({c:'',t:'<b>Icing penalty applied:</b> stall '+F(vsW,1)+' to '+F(vsIce,1)+' KIAS (+'+F(v.ice,0)+'%). Ice also lowers the stall angle of attack (buffet may never appear before the stall), degrades aileron effectiveness, and cuts elevator power - tailplane-stall risk rises with Mach.'});
  if(closed&&unitOK)adv.push({c:'bad',t:'<b>The usable band is CLOSED</b> at this altitude, weight, configuration and ice state. No speed is safe. Altitude is the only variable that helps.'});
  if(v.mach>0.80)adv.push({c:'',t:'Above M0.80: Mach tuck reduces elevator effectiveness. Do not pull at high Mach.'});
  if(A.dev!==0)adv.push({c:'info',t:'OAT is '+F(Math.abs(A.dev),1)+' deg C '+((A.dev>0)?'colder':'warmer')+' than ISA at this pressure altitude. Estimated geometric altitude about '+K(A.geom)+' ft.'});
  return {A:A,vsW:vsW,vsIce:vsIce,Mstall:Mstall,MstallClean:MstallClean,iasNow:iasNow,tasNow:tasNow,
    ceilM:ceilM,mmoLbl:mmoLbl,iasCeil:iasCeil,tasCeil:tasCeil,floorM:floorM,ceilPol:ceilPol,
    closed:closed,rawBandKt:rawBandKt,winKt:winKt,qNow:qNow,qCeil:qCeil,densFac:densFac,spdFac:spdFac,
    qRatio:qRatio,stepOn:stepOn,mmoEff:mmoEff,mFromVmo:mFromVmo,aSig:aSig,unitOK:unitOK,
    stallKt:stallKt,ceilKt:ceilKt,verdict:verdict,vcls:vcls,reasons:reasons,actions:actions,adv:adv};
}

function render(){
  var res=resolve(),v=res.val,r=compute(v);
  var ve=$('verdict');
  if(ve){ve.className='v '+r.vcls;ve.innerHTML=r.verdict+'<small>'+r.reasons.join(' ')+'</small>';}
  var rows=[];
  function row(l,M,tas,ias){
    var yy=(l.indexOf('YOUR MACH')>=0);
    rows.push('<tr'+(yy?' style="font-weight:700"':'')+'><td>'+l+'</td><td>'+F(M,3)+'</td><td>'+K(tas)+'</td><td>'+K(ias)+'</td><td>'+(ias===null?'--':F(ias-r.vsIce,1))+'</td><td>'+F(M-v.mach,3)+'</td></tr>');
  }
  row('Stall - clean',r.MstallClean,r.MstallClean*r.A.aKt,r.vsW);
  row('Stall - +'+v.ice+'% ice',r.Mstall,r.Mstall*r.A.aKt,r.vsIce);
  row('Policy floor (stall +'+v.mStall+' kt)',r.floorM,r.floorM*r.A.aKt,r.vsIce+v.mStall);
  row('YOUR MACH',v.mach,r.tasNow,r.iasNow);
  row('Policy ceiling (limit -'+v.mVmo+' kt)',r.ceilPol,r.ceilPol*r.A.aKt,r.iasCeil-v.mVmo);
  row('Ceiling - '+r.mmoLbl,r.ceilM,r.tasCeil,r.iasCeil);
  var bt=$('bt');if(bt)bt.getElementsByTagName('tbody')[0].innerHTML=rows.join('');
  var qr=[];
  function qrow(l,M){var VV=M*r.A.aMs,q=0.5*r.A.rho*VV*VV;
    qr.push('<tr><td>'+l+'</td><td>'+F(M,3)+'</td><td>'+K(M*r.A.aKt)+'</td><td>'+F(q,0)+'</td><td>'+F(q/PSF,0)+'</td><td>'+F(q/REF.q,2)+'x</td></tr>');}
  qrow('Your Mach',v.mach);qrow('Policy ceiling',r.ceilPol);qrow('Hard ceiling ('+r.mmoLbl+')',r.ceilM);qrow('Stall +'+v.ice+'% ice',r.Mstall);
  var qt=$('qt');if(qt)qt.getElementsByTagName('tbody')[0].innerHTML=qr.join('');
  function KC(l,val,s,c){return '<div class="k '+c+'"><div class="l">'+l+'</div><div class="v">'+val+'</div><div class="s">'+s+'</div></div>';}
  var cS=r.stallKt<0?'bad':(r.stallKt<v.mStall?'warn':'good');
  var cC=r.ceilKt<0?'bad':(r.ceilKt<v.mVmo?'warn':'good');
  H('kv',
    KC('Stall margin',F(v.mach-r.Mstall,3),F(r.stallKt,1)+' kt above the icing stall',cS)+
    KC('Overspeed margin',F(r.ceilM-v.mach,3),F(r.ceilKt,1)+' kt below the ceiling',cC)+
    KC('q at your Mach',F(r.qNow/PSF,0)+' psf',F(r.qNow,0)+' Pa',r.qRatio>1.2?'warn':'info')+
    KC('q vs cruise',F(r.qRatio,2)+'x',F(r.densFac,2)+' density x '+F(r.spdFac,2)+' speed',r.qRatio>1.5?'warn':'')+
    KC('q vs limit q',F(r.qNow/r.qCeil,3)+'x','(M/MMO) squared',r.qNow/r.qCeil>1?'bad':'good')+
    KC('Your IAS',K(r.iasNow)+' K','TAS '+K(r.tasNow)+' kt','')+
    KC('Icing stall',K(r.vsIce)+' K','M'+F(r.Mstall,3)+' - clean '+K(r.vsW)+' K','info')+
    KC('Ceiling','M'+F(r.ceilM,3),r.mmoLbl+' - '+K(r.iasCeil)+' K','info')+
    KC('Sound speed a',K(r.A.aKt)+' kt',F(r.A.aMs,1)+' m/s = '+F(r.A.aMph,1)+' mph','info')+
    KC('a * sqrt(sigma)',K(r.A.aSig)+' kt','IAS per unit Mach','info')+
    KC('Pressure altitude',N(v.alt)+' ft','ISA here '+F(r.A.Tc_isa,1)+' deg C','')+
    KC('OAT',v.oat===null?'ISA':F(v.oat,0)+' deg C','ISA deviation '+F(r.A.dev,1)+' deg C','info'));
  T('hnote','Raw band (hard boundaries) = '+F(r.rawBandKt,1)+' kt ('+F(r.ceilM-r.Mstall,3)+' Mach). Policy window = '+F(r.winKt,1)+' kt (M'+F(r.floorM,3)+' to M'+F(r.ceilPol,3)+'). Reference cruise for q = 35,000 ft, M0.76, ISA, q = '+F(REF.q/PSF,0)+' psf.');
  var wtxt='';
  if(res.issues.length)wtxt+='<div class="nb">Input notes: '+res.issues.join('; ')+'</div>';
  r.adv.forEach(function(a){wtxt+='<div class="nb '+a.c+'">'+a.t+'</div>';});
  if(r.actions.length)wtxt+='<div class="nb info"><b>RECOMMENDED ACTION:</b> '+r.actions.join(' ')+'</div>';
  H('adv',wtxt);
  var A=r.A;
  T('work',
'ATMOSPHERE\n'+
'  h_m   = '+N(v.alt)+' ft x 0.3048                       = '+F((v.alt||0)*0.3048,1)+' m\n'+
'  T_ISA = 288.15 - 0.0065*h_m                        = '+F(A.Tc_isa,2)+' deg C  ('+F(A.T_isa,2)+' K)\n'+
'  p     = 101325*(1 - 0.0065*h_m/288.15)^5.25588      = '+F(A.p,0)+' Pa\n'+
'  T     = '+(v.oat===null?'T_ISA (OAT blank)':(F(v.oat,1)+' deg C + 273.15'))+'                = '+F(A.T,2)+' K\n'+
'  rho   = p/(R*T) = '+F(A.p,0)+'/(287.053*'+F(A.T,2)+')         = '+F(A.rho,5)+' kg/m3\n'+
'  sigma = rho/1.225                                  = '+F(A.sig,5)+'\n'+
'  a     = sqrt(1.4*287.053*'+F(A.T,2)+')                 = '+F(A.aMs,2)+' m/s = '+F(A.aKt,1)+' kt = '+F(A.aMph,1)+' mph\n'+
'  a*sqrt(sigma) = a_kt*sqrt(sigma) = '+F(A.aKt,1)+'*'+F(A.ss,4)+'         = '+F(A.aSig,2)+' kt   (IAS per unit Mach)\n'+
'\nSTALL\n'+
'  Vs(W)   = '+F(v.vsRef,0)+'*sqrt('+N(v.weight)+'/'+N(v.wRef)+') + '+F(v.cfgInc,0)+'          = '+F(r.vsW,1)+' KIAS\n'+
'  Vs_ice  = '+F(r.vsW,1)+'*(1 + '+F(v.ice,0)+'%/100)              = '+F(r.vsIce,1)+' KIAS\n'+
'  Mstall  = Vs_ice/(a*sqrt(sigma)) = '+F(r.vsIce,1)+'/'+F(A.aSig,2)+'             = M'+F(r.Mstall,3)+'\n'+
'\nCEILING  (more restrictive limit binds)\n'+
'  MMO_eff = '+(r.stepOn?'stepped':'general')+'                       = M'+F(r.mmoEff,3)+'\n'+
'  M_VMO   = '+F(v.vmo,0)+'/'+F(A.aSig,2)+'                            = M'+F(r.mFromVmo,3)+'\n'+
'  Ceiling = min(MMO_eff, M_VMO)  ['+r.mmoLbl+']          = M'+F(r.ceilM,3)+'\n'+
'\nPOLICY WINDOW\n'+
'  Floor = ('+F(r.vsIce,1)+' + '+F(v.mStall,0)+')/'+F(A.aSig,2)+'                  = M'+F(r.floorM,3)+'\n'+
'  Ceiling_pol = M'+F(r.ceilM,3)+' - '+F(v.mVmo,0)+'/'+F(A.aSig,2)+'                  = M'+F(r.ceilPol,3)+'\n'+
'  Width       = ('+F(r.ceilPol,3)+' - '+F(r.floorM,3)+')*'+F(A.aSig,2)+'            = '+F(r.winKt,1)+' kt  '+(r.closed?'<  CLOSED':'')+'\n'+
'\nMARGINS\n'+
'  Stall margin   = M'+F(v.mach,3)+' - M'+F(r.Mstall,3)+'               = M'+F(v.mach-r.Mstall,3)+'   ('+F(r.stallKt,1)+' kt)\n'+
'  Ceiling margin = M'+F(r.ceilM,3)+' - M'+F(v.mach,3)+'               = M'+F(r.ceilM-v.mach,3)+'   ('+F(r.ceilKt,1)+' kt)\n'+
'\nq\n'+
'  V       = M*a = '+F(v.mach,3)+'*'+F(A.aMs,2)+'                 = '+F(v.mach*A.aMs,2)+' m/s\n'+
'  q       = 0.5*rho*V^2 = 0.5*'+F(A.rho,4)+'*'+F(v.mach*A.aMs,1)+'^2          = '+F(r.qNow,0)+' Pa = '+F(r.qNow/PSF,0)+' psf\n'+
'  q_ratio = (rho/rho_ref)*(V/V_ref)^2 = ('+F(r.densFac,3)+')*('+F(r.spdFac,3)+')   = '+F(r.qRatio,3)+'x cruise\n'+
'\nVERDICT: '+r.verdict);
  save();
}

function brief(){
  var res=resolve(),v=res.val,r=compute(v);
  var s='COFFIN CORNER BAND CHECK\n';
  s+='Alt '+N(v.alt)+' ft PA'+(v.oat!==null?(' / OAT '+F(v.oat,0)+' C'):' / ISA')+'  Wt '+N(v.weight)+' lb  Ice +'+F(v.ice,0)+'%  Mach M'+F(v.mach,3)+'\n';
  s+='Stall(ice) M'+F(r.Mstall,3)+' ('+K(r.vsIce)+' KIAS)   Ceiling M'+F(r.ceilM,3)+' ('+K(r.iasCeil)+' KIAS, '+r.mmoLbl+')\n';
  s+='Policy window M'+F(r.floorM,3)+' to M'+F(r.ceilPol,3)+'  ('+F(r.winKt,1)+' kt)'+(r.closed?'  ** CLOSED **':'')+'\n';
  s+='Margins: stall '+F(r.stallKt,1)+' kt  |  ceiling '+F(r.ceilKt,1)+' kt\n';
  s+='q '+F(r.qNow/PSF,0)+' psf ('+F(r.qRatio,2)+'x cruise)\n';
  s+='VERDICT: '+r.verdict+'\n'+r.reasons.join(' ')+'\n';
  if(r.actions.length)s+='ACTION: '+r.actions.join(' ')+'\n';
  s+='STUDY AID - verify every figure against your AFM.';
  return s;
}

function selfTest(){
  var out=[],fail=0;
  function chk(n,g,e,tol){
    var ok=Math.abs(g-e)<=(tol||0.05);
    if(!ok)fail++;
    out.push((ok?'PASS  ':'FAIL  ')+n+'   got '+g+'   expected '+e);
  }
  var snap={};var ids=['alt','oat','ice','mach','weight','wRef','vsRef','cfgInc','vmo','mmo','stepAlt','stepMach','mStall','mVmo'];
  ids.forEach(function(k){snap[k]=$(k)?$(k).value:'';});
  var oAlt=35000,oOat=-47,oIce=10,oMach=0.76,oMode=STEPMODE;
  function set(k,val){if($(k))$(k).value=val;}
